Gif_Stream* read_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    // Validate the GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler(GIF_INVALID_SIGNATURE, landmark);
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler(GIF_MEMORY_ALLOCATION_FAILURE, landmark);
        return NULL;
    }

    // Initialize necessary structures for reading GIF data
    stream->images = NULL;
    stream->extensions = NULL;

    // Process image blocks and extensions
    while (1) {
        int block_type = read_block(grr, read_flags);
        if (block_type == GIF_TERMINATOR) {
            break;
        } else if (block_type == GIF_IMAGE_BLOCK) {
            Gif_Image* image = process_image_block(grr, read_flags);
            if (!image) {
                handler(GIF_IMAGE_PROCESSING_FAILURE, landmark);
                free_stream(stream);
                return NULL;
            }
            add_image_to_stream(stream, image);
        } else if (block_type == GIF_EXTENSION_BLOCK) {
            Gif_Extension* ext = process_extension_block(grr, read_flags);
            if (!ext) {
                handler(GIF_EXTENSION_PROCESSING_FAILURE, landmark);
                free_stream(stream);
                return NULL;
            }
            add_extension_to_stream(stream, ext);
        } else {
            handler(GIF_UNKNOWN_BLOCK_TYPE, landmark);
            free_stream(stream);
            return NULL;
        }
    }

    return stream;
}

Gif_Stream* process_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    // Validate GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler(GIF_INVALID_SIGNATURE, landmark, NULL);
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler(GIF_MEMORY_ALLOCATION_FAILED, landmark, NULL);
        return NULL;
    }

    // Initialize GIF stream structure
    stream->images = NULL;
    stream->extensions = NULL;
    stream->size = 0;
    stream->capacity = 0;

    // Process image blocks and extensions
    while (1) {
        int block_type = read_next_block(grr, read_flags);
        if (block_type == GIF_TERMINATOR) {
            break;
        } else if (block_type == GIF_IMAGE_BLOCK) {
            Gif_Image* image = read_image_block(grr);
            if (!image) {
                handler(GIF_INVALID_IMAGE_BLOCK, landmark, NULL);
                goto cleanup;
            }

            // Add image to stream
            stream->images = (Gif_Image**)realloc(stream->images, (stream->size + 1) * sizeof(Gif_Image*));
            if (!stream->images) {
                handler(GIF_MEMORY_ALLOCATION_FAILED, landmark, NULL);
                goto cleanup;
            }

            stream->images[stream->size++] = image;
        } else if (block_type == GIF_EXTENSION_BLOCK) {
            Gif_Extension* extension = read_extension_block(grr);
            if (!extension) {
                handler(GIF_INVALID_EXTENSION_BLOCK, landmark, NULL);
                goto cleanup;
            }

            // Add extension to stream
            stream->extensions = (Gif_Extension**)realloc(stream->extensions, (stream->size + 1) * sizeof(Gif_Extension*));
            if (!stream->extensions) {
                handler(GIF_MEMORY_ALLOCATION_FAILED, landmark, NULL);
                goto cleanup;
            }

            stream->extensions[stream->size++] = extension;
        } else {
            handler(GIF_UNKNOWN_BLOCK_TYPE, landmark, NULL);
            goto cleanup;
        }
    }

    return stream;

cleanup:
    free(stream->images);
    free(stream->extensions);
    free(stream);
    return NULL;
}

Gif_Stream* read_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    // Validate GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler(GIF_ERROR_INVALID_SIGNATURE, grr, landmark);
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler(GIF_ERROR_MEMORY_ALLOCATION, grr, landmark);
        return NULL;
    }

    // Initialize GIF stream structure
    memset(stream, 0, sizeof(Gif_Stream));
    stream->reader = grr;
    stream->error_handler = handler;

    // Process GIF data blocks
    int result = process_gif_blocks(stream, read_flags);
    if (result != GIF_SUCCESS) {
        handler(result, stream->reader, landmark);
        free(stream);
        return NULL;
    }

    // Return the successfully created GIF stream
    return stream;
}

Gif_Stream* process_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        return NULL;
    }

    // Initialize the GIF stream structure
    memset(stream, 0, sizeof(Gif_Stream));

    // Validate the GIF signature
    if (!validate_gif_signature(grr, landmark)) {
        handler(GIF_ERROR_INVALID_SIGNATURE, NULL);
        free(stream);
        return NULL;
    }

    // Initialize necessary structures for reading GIF data
    if (!init_gif_data(grr, read_flags, stream)) {
        handler(GIF_ERROR_INIT_FAILURE, stream);
        free(stream);
        return NULL;
    }

    // Process image blocks, extensions, and terminators
    while (1) {
        Gif_BlockType block_type = read_gif_block(grr, stream);
        if (block_type == GIF_BLOCK_IMAGE) {
            if (!process_image_block(grr, stream)) {
                handler(GIF_ERROR_IMAGE_PROCESSING, stream);
                cleanup_gif_stream(stream);
                return NULL;
            }
        } else if (block_type == GIF_BLOCK_EXTENSION) {
            if (!process_extension_block(grr, stream)) {
                handler(GIF_ERROR_EXTENSION_PROCESSING, stream);
                cleanup_gif_stream(stream);
                return NULL;
            }
        } else if (block_type == GIF_BLOCK_TERMINATOR) {
            break;
        } else {
            handler(GIF_ERROR_UNKNOWN_BLOCK, stream);
            cleanup_gif_stream(stream);
            return NULL;
        }
    }

    return stream;
}

Gif_Stream* process_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    // Validate the GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler(GIF_INVALID_SIGNATURE, landmark);
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler(GIF_MEMORY_FAILURE, landmark);
        return NULL;
    }

    // Initialize stream structure
    stream->images = NULL;
    stream->image_count = 0;
    stream->extensions = NULL;
    stream->extension_count = 0;
    stream->error_handler = handler;

    // Process GIF data
    while (1) {
        int block_type = read_gif_block(grr);
        if (block_type == GIF_BLOCK_IMAGE) {
            Gif_Image* image = read_gif_image(grr);
            if (!image) {
                destroy_gif_stream(stream);
                handler(GIF_IMAGE_READ_FAILURE, landmark);
                return NULL;
            }
            add_image_to_stream(stream, image);
        } else if (block_type == GIF_BLOCK_EXTENSION) {
            Gif_Extension* extension = read_gif_extension(grr);
            if (!extension) {
                destroy_gif_stream(stream);
                handler(GIF_EXTENSION_READ_FAILURE, landmark);
                return NULL;
            }
            add_extension_to_stream(stream, extension);
        } else if (block_type == GIF_BLOCK_TERMINATOR) {
            break;
        } else {
            handler(GIF_UNKNOWN_BLOCK_TYPE, landmark);
            destroy_gif_stream(stream);
            return NULL;
        }
    }

    return stream;
}
